using System.ComponentModel.DataAnnotations.Schema;
using Microsoft.EntityFrameworkCore;

namespace WorldMapStudio.WoW;

/// <summary>EF Core row for the `command` table, generated by `database_tool generate-wms`.</summary>
[Table("command")]
[PrimaryKey(nameof(Name))]
public sealed class CommandRecord
{
    [Column("name")]
    public string Name { get; set; } = string.Empty;

    [Column("security")]
    public int Security { get; set; }

    [Column("help")]
    public string? Help { get; set; }

    [Column("flags")]
    public int Flags { get; set; }
}

public sealed partial class WorldDbContext
{
    public DbSet<CommandRecord> Command => Set<CommandRecord>();
}

/// <summary>Registers `command` into WorldStorage's model.</summary>
[Subsystem(nameof(WorldStorage))]
public sealed class CommandTableConfiguration : ITableConfiguration
{
    public CommandTableConfiguration(WorldStorage storage)
    {
    }

    public void Configure(ModelBuilder model)
    {
        model.Entity<CommandRecord>();
    }
}
